<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { profileApi } from '../api/profile'
import PaginationBar from '../components/PaginationBar.vue'
const authorizations=ref<any[]>([]),drafts=ref<any[]>([]),advisors=ref<any[]>([]),selectedAdvisor=ref(''),error=ref(''),loading=ref(true),working=ref(''),page=ref(1),pageSize=ref(10),total=ref(0)
async function load(){loading.value=true;try{const a=(await profileApi.advisorAuthorizations(pageSize.value,(page.value-1)*pageSize.value)).data.data;authorizations.value=a.items;total.value=a.total;const d=(await profileApi.operationDrafts(pageSize.value,(page.value-1)*pageSize.value)).data.data;drafts.value=d.items;const staff=(await profileApi.staffAdvisors(pageSize.value,(page.value-1)*pageSize.value)).data.data;advisors.value=staff.items}catch(e:any){error.value=e.response?.data?.detail?.message||e.message}finally{loading.value=false}}
async function chooseAdvisor(){if(!selectedAdvisor.value)return;working.value='advisor';try{await profileApi.createAdvisorAuthorization({advisor_id:selectedAdvisor.value,allowed_actions:'buy',product_scope:'*',max_single_amount:50000,max_daily_amount:100000,risk_level_ceiling:'C2',requires_customer_confirmation:true});await load()}catch(e:any){error.value=e.response?.data?.detail?.message||e.message}finally{working.value=''}}
async function act(id:string,action:'confirm'|'reject'|'submit'){if(working.value)return;working.value=id+action;try{if(action==='confirm')await profileApi.confirmOperationDraft(id);if(action==='reject')await profileApi.rejectOperationDraft(id);if(action==='submit')await profileApi.submitOperationDraftOrder(id);await load()}catch(e:any){error.value=e.response?.data?.detail?.message||e.message}finally{working.value=''}}
function go(n:number){page.value=Math.max(1,n);load()}function changeSize(n:number){pageSize.value=n;page.value=1;load()}onMounted(load)
</script>
<template><section class="workspace-page"><div class="row-actions"><button class="button secondary" @click="$router.push('/customer-center')">返回客户中心</button><button class="button secondary" @click="$router.push('/')">返回前台空间</button></div><div class="section-heading"><div><span class="eyebrow">ADVISOR FLOW</span><h2>投顾服务</h2><p>当前可选工作人员：{{advisors.length}} 人。</p></div></div><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="empty">正在读取投顾信息…</div><template v-else><div class="panel-card"><h3>选择投顾</h3><div class="row-actions"><select v-model="selectedAdvisor" class="advisor-select"><option value="">请选择工作人员</option><option v-for="a in advisors" :key="a.id" :value="a.id">{{a.display_name}}（{{a.username}}）</option></select><button class="button" :disabled="!selectedAdvisor||working==='advisor'" @click="chooseAdvisor">确认选择</button></div></div><div class="panel-card"><h3>当前授权</h3><div v-if="!authorizations.length" class="empty">暂无 active 投顾授权</div><div v-for="a in authorizations" :key="a.id" class="list-row"><div><strong>{{a.advisor_name||a.advisor_id}}</strong><small>{{a.allowed_actions}} · 单笔上限 ¥{{a.max_single_amount}} · 风险上限 {{a.risk_level_ceiling}}</small></div><span class="status-badge active">{{a.status}}</span></div></div><div class="panel-card"><h3>操作草稿</h3><div v-if="!drafts.length" class="empty">暂无操作草稿</div><div v-for="d in drafts" :key="d.id" class="list-row"><div><strong>{{d.side}} · ¥{{d.amount}}</strong><small>{{d.product_name||d.product_id}} · 顾问：{{d.advisor_name||d.advisor_id}} · {{d.status}}</small></div><div class="row-actions"><button v-if="d.status==='pending_customer_confirmation'" class="button secondary" @click="act(d.id,'reject')">拒绝</button><button v-if="d.status==='pending_customer_confirmation'" class="button" @click="act(d.id,'confirm')">确认草稿</button><button v-if="d.status==='customer_confirmed'" class="button" @click="act(d.id,'submit')">提交订单</button></div></div></div><PaginationBar :page="page" :page-size="pageSize" :total="total" @change="go" @size-change="changeSize"/></template></section></template>

